sql-service.query:
BEGIN TRANSACTION; UPDATE ms_script_mng SET QST_FOCUS = ?QST_FOCUS , QST_SECRET = ?QST_SECRET , CHG_ID = ?CHG_ID , CHG_DATE = format(GETDATE(),'yyyyMMddHHmmss') FROM ms_script_mng a, ms_script_sent b WHERE -- 조인조건 a.SC_SNO= b.SC_SNO and a.SC_LCLF_CD=b.SC_LCLF_CD and a.SC_SCLF_CD=b.SC_SCLF_CD and a.QST_CD=b.QST_CD and a.CNTR_CD=b.CNTR_CD AND A.DEL_YN = 'N' -- 파라미터 and a.SC_SNO = ?SC_SNO and a.SC_LCLF_CD = ?SC_LCLF_CD and a.SC_SCLF_CD = ?SC_SCLF_CD and a.QST_CD = ?QST_CD and a.CNTR_CD = ?CNTR_CD and b.SCRIPT_SENT_ID = ?SCRIPT_SENT_ID
UPDATE ms_script_sent SET QST_RATE = ?QST_RATE ,QST_KEYWORD = CASE WHEN LEN(?QST_KEYWORD) = 0 THEN NULL ELSE ?QST_KEYWORD END ,EXCEPT_YN = ?EXCEPT_YN , CHG_ID = ?CHG_ID , CHG_DATE = format(GETDATE(),'yyyyMMddHHmmss') FROM ms_script_mng a, ms_script_sent b WHERE -- 조인조건 a.SC_SNO= b.SC_SNO and a.SC_LCLF_CD=b.SC_LCLF_CD and a.SC_SCLF_CD=b.SC_SCLF_CD and a.QST_CD=b.QST_CD and a.CNTR_CD=b.CNTR_CD AND A.DEL_YN = 'N' -- 파라미터 and a.SC_SNO = ?SC_SNO and a.SC_LCLF_CD = ?SC_LCLF_CD and a.SC_SCLF_CD = ?SC_SCLF_CD and a.QST_CD = ?QST_CD and a.CNTR_CD = ?CNTR_CD and b.SCRIPT_SENT_ID = ?SCRIPT_SENT_ID
commit;

BEGIN TRANSACTION; UPDATE ms_script_mng SET QST_FOCUS = ?QST_FOCUS , QST_SECRET = ?QST_SECRET , CHG_ID = ?CHG_ID , CHG_DATE = format(GETDATE(),'yyyyMMddHHmmss') FROM ms_script_mng a, ms_script_sent b WHERE -- 조인조건 a.SC_SNO= b.SC_SNO and a.SC_LCLF_CD=b.SC_LCLF_CD and a.SC_SCLF_CD=b.SC_SCLF_CD and a.QST_CD=b.QST_CD and a.CNTR_CD=b.CNTR_CD AND A.DEL_YN = 'N' -- 파라미터 and a.SC_SNO = ?SC_SNO and a.SC_LCLF_CD = ?SC_LCLF_CD and a.SC_SCLF_CD = ?SC_SCLF_CD and a.QST_CD = ?QST_CD and a.CNTR_CD = ?CNTR_CD and b.SCRIPT_SENT_ID = ?SCRIPT_SENT_ID
UPDATE ms_script_sent SET QST_RATE = ?QST_RATE ,QST_KEYWORD = CASE WHEN LEN(?QST_KEYWORD) = 0 THEN NULL ELSE ?QST_KEYWORD END ,EXCEPT_YN = ?EXCEPT_YN , CHG_ID = ?CHG_ID , CHG_DATE = format(GETDATE(),'yyyyMMddHHmmss') FROM ms_script_mng a, ms_script_sent b WHERE -- 조인조건 a.SC_SNO= b.SC_SNO and a.SC_LCLF_CD=b.SC_LCLF_CD and a.SC_SCLF_CD=b.SC_SCLF_CD and a.QST_CD=b.QST_CD and a.CNTR_CD=b.CNTR_CD AND A.DEL_YN = 'N' -- 파라미터 and a.SC_SNO = ?SC_SNO and a.SC_LCLF_CD = ?SC_LCLF_CD and a.SC_SCLF_CD = ?SC_SCLF_CD and a.QST_CD = ?QST_CD and a.CNTR_CD = ?CNTR_CD and b.SCRIPT_SENT_ID = ?SCRIPT_SENT_ID
commit;

BEGIN TRANSACTION; UPDATE tb_sc_qst_mng SET DEL_YN = 'Y', DEL_DATE = ?DEL_DATE WHERE SC_SNO = ?SC_SNO AND SC_LCLF_CD = ?SC_LCLF_CD AND SC_SCLF_CD = ?SC_SCLF_CD AND QST_CD = ?QST_CD AND CNTR_CD = ?CNTR_CD
UPDATE ms_script_mng SET DEL_YN = 'Y', DEL_DATE = ?DEL_DATE WHERE SC_SNO = ?SC_SNO AND SC_LCLF_CD = ?SC_LCLF_CD AND SC_SCLF_CD = ?SC_SCLF_CD AND QST_CD = ?QST_CD AND CNTR_CD = ?CNTR_CD
UPDATE ms_script_sent SET DEL_YN = 'Y', DEL_DATE = ?DEL_DATE WHERE SC_SNO = ?SC_SNO AND SC_LCLF_CD = ?SC_LCLF_CD AND SC_SCLF_CD = ?SC_SCLF_CD AND QST_CD = ?QST_CD AND CNTR_CD = ?CNTR_CD COMMIT;

BEGIN TRANSACTION; UPDATE tb_sc_qst_mng SET DEL_YN = 'N', DEL_DATE = NULL WHERE DEL_DATE BETWEEN ?SDATE AND ?EDATE AND DEL_YN = 'Y'
UPDATE ms_script_mng SET DEL_YN = 'N', DEL_DATE = NULL WHERE DEL_DATE BETWEEN ?SDATE AND ?EDATE AND DEL_YN = 'Y'
UPDATE ms_script_sent SET DEL_YN = 'N', DEL_DATE = NULL WHERE DEL_DATE BETWEEN ?SDATE AND ?EDATE AND DEL_YN = 'Y' COMMIT;

SELECT COUNT(1) CNT
from ms_script_mng WITH(NOLOCK)
WHERE CHG_DATE BETWEEN ?SDATE AND ?EDATE

BEGIN TRANSACTION;		
UPDATE ms_script_mng SET DEL_YN = 'Y', DEL_DATE = ?DEL_DATE
WHERE SC_SNO = ?SC_SNO AND SC_LCLF_CD = ?SC_LCLF_CD AND SC_SCLF_CD = ?SC_SCLF_CD AND QST_CD = ?QST_CD AND CNTR_CD = ?CNTR_CD

UPDATE ms_script_sent SET DEL_YN = 'Y', DEL_DATE = ?DEL_DATE
WHERE SC_SNO = ?SC_SNO AND SC_LCLF_CD = ?SC_LCLF_CD AND SC_SCLF_CD = ?SC_SCLF_CD AND QST_CD = ?QST_CD AND CNTR_CD = ?CNTR_CD
COMMIT;

BEGIN TRANSACTION;		
UPDATE ms_script_mng SET DEL_YN = 'N', DEL_DATE = NULL
WHERE DEL_DATE BETWEEN ?SDATE AND ?EDATE AND DEL_YN = 'Y'

UPDATE ms_script_sent SET DEL_YN = 'N', DEL_DATE = NULL
WHERE DEL_DATE BETWEEN ?SDATE AND ?EDATE AND DEL_YN = 'Y'
COMMIT;
